<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $query=function_exists('nvconsult_v2_get_featured_countries')?nvconsult_v2_get_featured_countries(8):new WP_Query(array('post_type'=>'nvconsult_country','post_status'=>'publish','posts_per_page'=>8,'orderby'=>array('menu_order'=>'ASC','title'=>'ASC'))); ?>
<section class="section"><div class="section-inner"><?php nvconsultv2_render_section_heading( 'featured-destinations', __( 'Featured Destinations', 'nvconsult-theme-v2' ), __( 'Explore countries with strong study and work opportunities.', 'nvconsult-theme-v2' ) ); ?><?php if($query->have_posts()): ?><div class="destinations-wrap"><div class="carousel-controls"><button type="button" class="carousel-button" data-destinations-prev aria-label="<?php esc_attr_e( 'Previous destinations', 'nvconsult-theme-v2' ); ?>">&#8592;</button><button type="button" class="carousel-button" data-destinations-next aria-label="<?php esc_attr_e( 'Next destinations', 'nvconsult-theme-v2' ); ?>">&#8594;</button></div><div class="destinations-carousel"><?php while($query->have_posts()): $query->the_post(); $flag=get_post_meta(get_the_ID(),'_nvconsult_flag_image',true); $description=get_post_meta(get_the_ID(),'_nvconsult_description',true); ?><article class="destination-card"><div class="destination-card__image"><?php if(has_post_thumbnail()): the_post_thumbnail('large'); else: ?><div class="destination-card__image"></div><?php endif; ?></div><div class="destination-card__body"><?php if($flag): ?><div class="destination-card__flag"><img src="<?php echo esc_url( $flag ); ?>" alt="<?php echo esc_attr( get_the_title() ); ?>"></div><?php endif; ?><h3><?php the_title(); ?></h3><p><?php echo esc_html( $description ? wp_trim_words( $description, 18 ) : get_the_excerpt() ); ?></p><a class="btn-outline" href="<?php the_permalink(); ?>"><?php esc_html_e( 'Explore →', 'nvconsult-theme-v2' ); ?></a></div></article><?php endwhile; wp_reset_postdata(); ?></div></div><?php else: ?><div class="placeholder-message"><?php esc_html_e( 'Add countries in wp-admin → Countries', 'nvconsult-theme-v2' ); ?></div><?php endif; ?></div></section>
